fn is_prime(n: i8) -> bool {
    // Handle edge cases: numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 to n-1
    let mut k: i8 = 2;
    while k < n {
        // If n is divisible by k, it's not prime
        if n % k == 0 {
            return false;
        }
        k += 1;
    }
    
    // No divisors found, so n is prime
    true
}